import React, { useCallback, useEffect, useState } from 'react';
import {
  Area,
  Bar,
  CartesianGrid,
  ComposedChart,
  Legend,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import {
  Button,
  FormActions,
  Input,
  dispatchAppToast,
} from '@linm-soft-org/linm-web-common-components';
import { Spin, Text, Title } from '@/components/common';
import { useAppDispatch } from '../../../store/hooks';
import { fpcService } from '../../../services/fpc/service';
import type { DailyCashForecastDto } from '../../../services/fpc/types';
import { useFpcPermissions } from '../../../utils/fpcPermissionCode';
import styles from './DailyCashForecastPage.module.css';

const TEST_ID = 'daily-cash-forecast';

const fVnd = (v: number): string =>
  new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(v);

const fCompact = (v: number): string => {
  const abs = Math.abs(v);
  const sign = v < 0 ? '-' : '';
  if (abs >= 1_000_000_000) return `${sign}${(abs / 1_000_000_000).toFixed(1)} tỷ`;
  if (abs >= 1_000_000) return `${sign}${(abs / 1_000_000).toFixed(0)} tr`;
  if (abs >= 1_000) return `${sign}${(abs / 1_000).toFixed(0)} ng`;
  return `${v.toLocaleString('vi-VN')}`;
};

const chartCurrency = (v: number): string => `${(v / 1_000_000).toFixed(0)}tr`;

function todayLocalYmd(): string {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function addDaysYmd(ymd: string, days: number): string {
  const [y, m, d] = ymd.split('-').map(Number);
  const dt = new Date(y, m - 1, d);
  dt.setDate(dt.getDate() + days);
  const yy = dt.getFullYear();
  const mm = String(dt.getMonth() + 1).padStart(2, '0');
  const dd = String(dt.getDate()).padStart(2, '0');
  return `${yy}-${mm}-${dd}`;
}

function formatDisplayDate(isoOrYmd?: string | null): string {
  if (!isoOrYmd) return '—';
  const raw = isoOrYmd.slice(0, 10);
  const [y, m, d] = raw.split('-');
  if (!y || !m || !d) return isoOrYmd;
  return `${d}/${m}/${y}`;
}

function alertLabel(status: string): string {
  if (status === 'critical') return 'Nguy cấp';
  if (status === 'warning') return 'Cảnh báo';
  return 'An toàn';
}

const DailyCashForecastPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const { canViewDailyCash, canExportReports } = useFpcPermissions();

  const defaultFrom = todayLocalYmd();
  const defaultTo = addDaysYmd(defaultFrom, 13);

  const [fromDate, setFromDate] = useState(defaultFrom);
  const [toDate, setToDate] = useState(defaultTo);
  const [appliedFrom, setAppliedFrom] = useState(defaultFrom);
  const [appliedTo, setAppliedTo] = useState(defaultTo);
  const [data, setData] = useState<DailyCashForecastDto | null>(null);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState(false);

  const loadReport = useCallback(async (from: string, to: string) => {
    setLoading(true);
    setLoadError(false);
    try {
      const result = await fpcService.getDailyForecast({ fromDate: from, toDate: to });
      setData(result);
      setAppliedFrom(from);
      setAppliedTo(to);
    } catch {
      setData(null);
      setLoadError(true);
      dispatchAppToast(dispatch, {
        message: 'Không thể tải dự báo tiền hàng ngày',
        type: 'error',
      });
    } finally {
      setLoading(false);
    }
  }, [dispatch]);

  useEffect(() => {
    const t = window.setTimeout(() => {
      void loadReport(appliedFrom, appliedTo);
    }, 0);
    return () => window.clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- initial load; Xem/Làm mới gọi loadReport
  }, []);

  const handleView = () => {
    if (!fromDate || !toDate) {
      dispatchAppToast(dispatch, { message: 'Vui lòng chọn từ ngày / đến ngày', type: 'error' });
      return;
    }
    if (fromDate > toDate) {
      dispatchAppToast(dispatch, { message: 'Từ ngày phải trước hoặc bằng Đến ngày', type: 'error' });
      return;
    }
    void loadReport(fromDate, toDate);
  };

  const handleRefresh = () => {
    void loadReport(appliedFrom, appliedTo);
  };

  if (!canViewDailyCash) {
    return (
      <div className={styles.page} data-testid={`${TEST_ID}-page`}>
        <div className={styles.empty}>
          <Text type="secondary">Bạn không có quyền xem dự báo tiền hàng ngày.</Text>
        </div>
      </div>
    );
  }

  const days = data?.days ?? [];
  const inflowLines = data?.inflowLines ?? [];
  const outflowLines = data?.outflowLines ?? [];
  const totalInflow = data?.totalInflow ?? 0;
  const totalOutflow = data?.totalOutflow ?? 0;

  return (
    <div className={styles.page} data-testid={`${TEST_ID}-page`}>
      <div className={styles.headerCard}>
        <div className={styles.headerTop}>
          <div>
            <Title level={4}>
              <i className="fas fa-calendar-day" style={{ marginRight: 8, color: '#059669' }} />
              Dự báo tiền hàng ngày
            </Title>
            <Text type="secondary">
              Dự báo số dư · khả dụng · trạng thái theo ngày
              {appliedFrom && appliedTo
                ? ` · Kỳ: ${formatDisplayDate(appliedFrom)} – ${formatDisplayDate(appliedTo)}`
                : ''}
            </Text>
          </div>
          <FormActions align="end">
            <Button onClick={handleRefresh} data-testid={`${TEST_ID}-refresh-btn`}>
              <i className="fas fa-redo" /> Làm mới
            </Button>
            {canExportReports && (
              <Button
                variant="secondary"
                disabled={!data}
                onClick={() => window.print()}
                data-testid={`${TEST_ID}-export-btn`}
              >
                <i className="fas fa-print" /> In
              </Button>
            )}
          </FormActions>
        </div>

        <div className={styles.filterRow}>
          <div className={styles.filterField}>
            <label className={styles.filterLabel} htmlFor={`${TEST_ID}-from-date`}>Từ ngày</label>
            <Input
              id={`${TEST_ID}-from-date`}
              type="date"
              value={fromDate}
              onChange={e => setFromDate(e.target.value)}
              data-testid={`${TEST_ID}-from-date`}
            />
          </div>
          <div className={styles.filterField}>
            <label className={styles.filterLabel} htmlFor={`${TEST_ID}-to-date`}>Đến ngày</label>
            <Input
              id={`${TEST_ID}-to-date`}
              type="date"
              value={toDate}
              onChange={e => setToDate(e.target.value)}
              data-testid={`${TEST_ID}-to-date`}
            />
          </div>
          <FormActions align="end">
            <Button variant="primary" onClick={handleView} data-testid={`${TEST_ID}-view-btn`}>
              <i className="fas fa-search" /> Xem
            </Button>
          </FormActions>
        </div>
      </div>

      {loading && (
        <div className={styles.loading} data-testid={`${TEST_ID}-loading`}>
          <Spin />
          <Text type="secondary">Đang tải dự báo…</Text>
        </div>
      )}

      {!loading && loadError && (
        <div className={styles.empty} data-testid={`${TEST_ID}-error`}>
          <Text type="secondary">Không tải được dữ liệu. Thử Làm mới hoặc đổi kỳ.</Text>
          <Button variant="primary" onClick={handleRefresh}>Thử lại</Button>
        </div>
      )}

      {!loading && !loadError && !data && (
        <div className={styles.empty} data-testid={`${TEST_ID}-empty`}>
          <Text type="secondary">Chưa có dữ liệu cho kỳ đã chọn.</Text>
        </div>
      )}

      {!loading && data && (
        <div className={styles.contentPanel} data-testid={`${TEST_ID}-content`}>
          <div className={styles.statsRow}>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Đầu kỳ</span>
              <span className={styles.statValue}>{fCompact(data.openingBalance)}</span>
            </div>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Tổng thu</span>
              <span className={`${styles.statValue} ${styles.positive}`}>+{fCompact(data.totalInflow)}</span>
            </div>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Tổng chi</span>
              <span className={`${styles.statValue} ${styles.negative}`}>-{fCompact(data.totalOutflow)}</span>
            </div>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Dòng tiền thuần</span>
              <span className={`${styles.statValue} ${data.netCashflow >= 0 ? styles.positive : styles.negative}`}>
                {data.netCashflow >= 0 ? '+' : ''}{fCompact(data.netCashflow)}
              </span>
            </div>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Chi bắt buộc</span>
              <span className={styles.statValue}>{fCompact(data.mandatoryOutflow)}</span>
            </div>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Tiền khả dụng</span>
              <span className={`${styles.statValue} ${data.availableBalance >= 0 ? styles.positive : styles.negative}`}>
                {fCompact(data.availableBalance)}
              </span>
            </div>
          </div>

          <div className={styles.chartCardFull}>
            <div className={styles.chartCardHeader}>
              <h3 className={styles.chartTitle}>Thu / chi theo ngày</h3>
              <span className={styles.sectionBadge}>Cột thu+chi cùng ngày · {days.length} ngày</span>
            </div>
            {days.length > 0 ? (
              <ResponsiveContainer width="100%" height={320}>
                <ComposedChart data={days}>
                  <defs>
                    <linearGradient id="colorClosing" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#059669" stopOpacity={0.25} />
                      <stop offset="95%" stopColor="#059669" stopOpacity={0} />
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
                  <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                  <YAxis tickFormatter={chartCurrency} tick={{ fontSize: 11 }} />
                  <Tooltip formatter={(v: number) => fVnd(v)} />
                  <Legend />
                  <Bar
                    dataKey="inflowPlanned"
                    name="Thu"
                    fill="#10b981"
                    radius={[2, 2, 0, 0]}
                    maxBarSize={28}
                  />
                  <Bar
                    dataKey="outflowPlanned"
                    name="Chi"
                    fill="#f43f5e"
                    radius={[2, 2, 0, 0]}
                    maxBarSize={28}
                  />
                  <Area
                    type="monotone"
                    dataKey="closingBalance"
                    name="Số dư cuối ngày"
                    stroke="#2563eb"
                    fill="url(#colorClosing)"
                    strokeWidth={2}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            ) : (
              <Text type="secondary">Chưa có dữ liệu ngày trong kỳ.</Text>
            )}
          </div>

          <div className={styles.tableWrapper}>
            <table className={styles.table} data-testid={`${TEST_ID}-days-table`}>
              <thead>
                <tr>
                  <th>Ngày</th>
                  <th>Đầu kỳ</th>
                  <th>Thu</th>
                  <th>Chi</th>
                  <th>Cuối kỳ</th>
                  <th>Khả dụng</th>
                  <th>Trạng thái</th>
                </tr>
              </thead>
              <tbody>
                {days.length === 0 ? (
                  <tr>
                    <td colSpan={7}>
                      <Text type="secondary">Không có dòng ngày.</Text>
                    </td>
                  </tr>
                ) : (
                  days.map((day, i) => (
                    <tr
                      key={`${day.date}-${i}`}
                      className={
                        day.alertStatus === 'critical'
                          ? styles.rowCritical
                          : day.alertStatus === 'warning'
                            ? styles.rowWarning
                            : undefined
                      }
                    >
                      <td style={{ fontWeight: 500 }}>{day.label}</td>
                      <td className={styles.colAmount}>{fVnd(day.openingBalance)}</td>
                      <td className={styles.colAmount}>{fVnd(day.inflowPlanned)}</td>
                      <td className={styles.colAmount}>{fVnd(day.outflowPlanned)}</td>
                      <td className={styles.colAmount} style={{ fontWeight: 600 }}>{fVnd(day.closingBalance)}</td>
                      <td className={styles.colAmount}>
                        <span className={day.availableBalance >= 0 ? styles.positive : styles.negative}>
                          {fVnd(day.availableBalance)}
                        </span>
                      </td>
                      <td className={styles.colCenter}>
                        <span
                          className={`${styles.alertDot} ${
                            day.alertStatus === 'critical'
                              ? styles.alertRed
                              : day.alertStatus === 'warning'
                                ? styles.alertYellow
                                : styles.alertGreen
                          }`}
                        />
                        <span
                          className={
                            day.alertStatus === 'critical'
                              ? styles.statusRed
                              : day.alertStatus === 'warning'
                                ? styles.warning
                                : styles.statusGreen
                          }
                          style={{ fontSize: 11, marginLeft: 6 }}
                        >
                          {alertLabel(day.alertStatus)}
                        </span>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>

          <div className={styles.chartsRow}>
            <div className={styles.sectionCard}>
              <div className={styles.sectionHeader}>
                <h3 className={styles.sectionTitle}>Cơ cấu thu</h3>
                <span className={styles.sectionBadge}>{inflowLines.length} nhóm</span>
              </div>
              {inflowLines.length === 0 ? (
                <Text type="secondary">Chưa có dòng thu kế hoạch trong kỳ.</Text>
              ) : (
                inflowLines.map((line, i) => (
                  <div
                    key={`${line.categoryCode}-${i}`}
                    className={styles.breakdownRow}
                    style={{ borderBottom: i < inflowLines.length - 1 ? '1px solid #f1f5f9' : 'none' }}
                  >
                    <div className={styles.breakdownMeta}>
                      <div className={styles.breakdownName}>{line.categoryName}</div>
                      <div className={styles.breakdownSub}>{line.lineCount} giao dịch</div>
                    </div>
                    <div className={styles.barTrack}>
                      <div
                        className={styles.barFill}
                        style={{
                          width: `${totalInflow > 0 ? Math.min(100, (line.amount / totalInflow) * 100) : 0}%`,
                          background: '#10b981',
                        }}
                      />
                    </div>
                    <span className={styles.breakdownAmount}>{fCompact(line.amount)}</span>
                  </div>
                ))
              )}
            </div>

            <div className={styles.sectionCard}>
              <div className={styles.sectionHeader}>
                <h3 className={styles.sectionTitle}>Cơ cấu chi</h3>
                <span className={styles.sectionBadge}>{outflowLines.length} nhóm</span>
              </div>
              {outflowLines.length === 0 ? (
                <Text type="secondary">Chưa có dòng chi kế hoạch trong kỳ.</Text>
              ) : (
                outflowLines.map((line, i) => (
                  <div
                    key={`${line.categoryCode}-${i}`}
                    className={styles.breakdownRow}
                    style={{ borderBottom: i < outflowLines.length - 1 ? '1px solid #f1f5f9' : 'none' }}
                  >
                    <div className={styles.breakdownMeta}>
                      <div className={styles.breakdownName}>
                        {line.categoryName}
                        {line.isMandatory && (
                          <span className={styles.mandatoryBadge}>Bắt buộc</span>
                        )}
                      </div>
                      <div className={styles.breakdownSub}>{line.lineCount} giao dịch</div>
                    </div>
                    <div className={styles.barTrack}>
                      <div
                        className={styles.barFill}
                        style={{
                          width: `${totalOutflow > 0 ? Math.min(100, (line.amount / totalOutflow) * 100) : 0}%`,
                          background: line.isMandatory ? '#ef4444' : '#f59e0b',
                        }}
                      />
                    </div>
                    <span className={styles.breakdownAmount}>{fCompact(line.amount)}</span>
                  </div>
                ))
              )}
            </div>
          </div>

          {data.nearestRedDate && (
            <div className={styles.hintCard} data-testid={`${TEST_ID}-red-date`}>
              <Text type="secondary">
                Ngày đỏ gần nhất: <strong>{formatDisplayDate(data.nearestRedDate)}</strong>
              </Text>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default DailyCashForecastPage;
